"""Independent direct simulation of the case/event lifecycle."""
import heapq


def simulate(cases, events, timeout_ms):
    streams = [4 * i for i in range(len(cases))]
    state = [None] * len(cases)
    at = [None] * len(cases)
    index = [0] * len(cases)
    send_ended = [False] * len(cases)
    response_ended = [False] * len(cases)
    waiting = [False] * len(cases)
    connection_closed = [False]
    sent_log = [[] for _ in cases]
    recv_log = [[] for _ in cases]
    body_parts = [[] for _ in cases]
    heap = []
    counter = [0]

    def push(time, kind, order, action):
        counter[0] += 1
        heapq.heappush(heap, (time, kind, order, counter[0], action))

    for i in range(len(cases)):
        push(0, -1, i, ('start', i))
    for j, event in enumerate(events):
        push(event['at'], 0, j, ('event', j))

    def run_frames(i, now):
        while index[i] < len(cases[i]['frames']):
            item = cases[i]['frames'][index[i]]
            if item['Type'] == 'sleep':
                index[i] += 1
                push(now + item['Time_to_Stop'], 1, i, ('resume', i))
                return
            if send_ended[i]:
                state[i] = 'send_error'
                at[i] = now
                return
            index[i] += 1
            if item['Type'] == 'headers':
                sent_log[i].append((now, 'H', item['data_to_transfered'], item['End_Stream']))
                if item['End_Stream']:
                    send_ended[i] = True
            elif item['Type'] == 'data':
                sent_log[i].append((now, 'D', item['data_to_transfered'], item['End_Stream']))
                if item['End_Stream']:
                    send_ended[i] = True
            else:
                sent_log[i].append((now, 'G', item['data_to_transfered'], False))
        if response_ended[i]:
            state[i] = 'ok'
            at[i] = now
        else:
            waiting[i] = True
            push(now + timeout_ms, 2, i, ('timeout', i))

    while heap:
        now, _, _, _, action = heapq.heappop(heap)
        tag = action[0]
        if tag in ('start', 'resume'):
            i = action[1]
            if state[i] is None:
                run_frames(i, now)
        elif tag == 'timeout':
            i = action[1]
            if state[i] is None and waiting[i]:
                state[i] = 'timeout'
                at[i] = now
        else:
            event = events[action[1]]
            if event['kind'] == 'close':
                if connection_closed[0]:
                    continue
                connection_closed[0] = True
                for i in range(len(cases)):
                    if state[i] is None:
                        state[i] = 'closed'
                        at[i] = now
            else:
                stream = event['stream']
                if stream not in streams:
                    continue
                i = streams.index(stream)
                if state[i] is not None or response_ended[i]:
                    continue
                if event['kind'] == 'headers':
                    recv_log[i].append((now, 'h', event['fields'], event['end']))
                else:
                    recv_log[i].append((now, 'd', event['data'], event['end']))
                    body_parts[i].append(event['data'])
                if event['end']:
                    response_ended[i] = True
                    if waiting[i] and state[i] is None:
                        state[i] = 'ok'
                        at[i] = now
    out = []
    for i, case in enumerate(cases):
        frames = len(sent_log[i])
        request_frames = sum(1 for entry in sent_log[i] if entry[1] in ('H', 'D'))
        payload = 0
        for _, kind, data, _ in sent_log[i]:
            if kind == 'H':
                payload += sum(len(n) + len(v) for n, v in data)
            else:
                payload += len(data)
        out.append({'name': case['name'], 'stream': streams[i], 'state': state[i],
                    'at': at[i], 'frames': frames, 'request_frames': request_frames,
                    'payload_bytes': payload, 'sent': sent_log[i], 'received': recv_log[i],
                    'response_frames': len(recv_log[i]), 'body': body_parts[i]})
    return out
