"""Cross-check with template forms ({{ }} expressions and random tokens)."""
import hashlib
import json
import random
import subprocess
import sys

sys.path.insert(0, '/tmp/h3/ref')
import fuzz as base
from replay import simulate
import http as refhttp

PROG = ['python3', '-B', 'main.py']


def pybytes(data):
    out = ['b"']
    for byte in data:
        ch = chr(byte)
        if ch in '"\\':
            out.append('\\' + ch)
        elif ch == '\r':
            out.append('\\r')
        elif ch == '\n':
            out.append('\\n')
        elif ch == '\t':
            out.append('\\t')
        elif 0x20 <= byte <= 0x7e:
            out.append(ch)
        else:
            out.append('\\x%02x' % byte)
    out.append('"')
    return ''.join(out)


def token(seed, coord, occ):
    return hashlib.sha256(('%s/%s/%d' % (seed, coord, occ)).encode()).hexdigest()[:20].encode()


def resolve(data, seed, coord):
    if data.startswith('{{') and data.endswith('}}'):
        source = data[2:-2].strip()
        assert source.startswith('b"') and source.endswith('"'), source
        body = source[2:-1]
        out = bytearray()
        i = 0
        while i < len(body):
            ch = body[i]
            if ch == '\\':
                nxt = body[i + 1]
                if nxt == 'r':
                    out.append(13)
                elif nxt == 'n':
                    out.append(10)
                elif nxt == 't':
                    out.append(9)
                elif nxt == '\\':
                    out.append(92)
                elif nxt == '"':
                    out.append(34)
                elif nxt == 'x':
                    out.append(int(body[i + 2:i + 4], 16))
                    i += 4
                    continue
                else:
                    raise AssertionError(nxt)
                i += 2
            else:
                out.append(ord(ch))
                i += 1
        return bytes(out)
    pieces = data.split('<<random_string>>')
    out = bytearray()
    last = len(pieces) - 1
    for index, piece in enumerate(pieces):
        out += piece.encode('utf8')
        if index < last:
            out += token(seed, coord, index)
    return bytes(out)


def expected(doc):
