"""Offline payload compilation, client replay and origin evidence audit."""
import gc
import json
import math
import re
import sys
from pathlib import Path

# The local no-Docker worker stages the same pinned wheels here. In the public
# image the packages are installed normally and this directory is unnecessary.
if Path('/opt/h3deps').is_dir():
    sys.path.insert(0, '/opt/h3deps')

from modules.byte_program import Context
from schema import compile_cases
from modules.byte_program import MAX
from modules.fuzz_adapter import FuzzExecutor
from modules.capture_audit import TOKEN, audit_channels

NAME = re.compile(r'[A-Za-z0-9_.-]{1,32}\Z', re.ASCII)
SEED = re.compile(r'[A-Za-z0-9_.-]{0,64}\Z', re.ASCII)
ROOT_KEYS = ('seed', 'definitions', 'timeout_ms', 'cases', 'events', 'channels')
FRAME_KEYS = {
    'headers': (('Type', 'End_Stream', 'headers_kv', 'data_to_transfered'), ('Type',)),
    'data': (('Type', 'End_Stream', 'data_to_transfered'), ('Type', 'data_to_transfered')),
    'datagram': (('Type', 'End_Stream', 'data_to_transfered'), ('Type', 'data_to_transfered')),
    'sleep': (('Type', 'Time_to_Stop'), ('Type', 'Time_to_Stop')),
}
INPUT_LIMIT = 8 * 1024 ** 2
MAX_DEFINITIONS = 8192
MAX_CASES = 2000
MAX_CHANNELS = 256
COMBINED_BUDGET = 50000
PAIR_BUDGET = 32768
PAIRS_PER_BLOCK = 128
NAME_LIMIT = 32
EXPECT_LIMIT = 8192


class InputError(ValueError):
    """Any rejection of the input document."""


def exact(obj, keys):
    if type(obj) is not dict:
        raise InputError('object')
    if set(obj) != set(keys):
        raise InputError('object keys')


def integer(value, minimum=0, maximum=MAX):
    if type(value) is not int or not minimum <= value <= maximum:
        raise InputError('integer')
    return value


def sequence(value, maximum):
    if type(value) is not list or len(value) > maximum:
        raise InputError('array')
    return value


def text(value, maximum=1 << 24):
    if type(value) is not str or len(value) > maximum:
        raise InputError('string')
    try:
        value.encode('utf8')
    except UnicodeEncodeError:
        raise InputError('string encoding') from None
    return value


def pairs(items):
    out = {}
    for key, value in items:
        if key in out:
            raise InputError('duplicate key')
        out[key] = value
    return out


def bad_constant(value):
    raise InputError('nonfinite JSON')


def finite_float(value):
    result = float(value)
    if not math.isfinite(result):
        raise InputError('nonfinite JSON')
    return result


def allow(obj, allowed, required):
    if type(obj) is not dict:
        raise InputError('object')
    keys = set(obj)
    if not keys <= set(allowed) or not set(required) <= keys:
        raise InputError('object keys')


def expect_identity(value):
    data = text(value, EXPECT_LIMIT).encode('ascii')
    if not data or not all(0x21 <= byte <= 0x7e for byte in data):
        raise InputError('expected identity')
    return data


def compile_frames(frames, context, case_index):
    """Validate and template-compile one case's frame list."""
    compiled = []
    pause_total = 0
    for index, frame in enumerate(frames):
        if type(frame) is not dict:
            raise InputError('frame')
        kind = frame.get('Type')
        if type(kind) is not str:
            raise InputError('frame type')
        kind = text(kind, NAME_LIMIT)
        if kind not in FRAME_KEYS:
            raise InputError('frame type')
        allow(frame, *FRAME_KEYS[kind])
        if kind == 'sleep':
            pause_total += integer(frame['Time_to_Stop'])
            compiled.append({'Type': 'sleep', 'Time_to_Stop': frame['Time_to_Stop']})
            continue
        end = frame.get('End_Stream', kind != 'headers')
        if type(end) is not bool:
            raise InputError('frame end')
        if kind == 'headers':
            has_mapping = 'headers_kv' in frame
            has_list = 'data_to_transfered' in frame
            if has_mapping == has_list:
                raise InputError('headers source')
            pairs_out = []
            if has_mapping:
                mapping = frame['headers_kv']
                if type(mapping) is not dict:
                    raise InputError('header mapping')
                items = list(mapping.items())
                if len(items) > PAIRS_PER_BLOCK:
                    raise InputError('header pairs')
                for pair_index, (key, value) in enumerate(items):
                    if type(key) is not str or type(value) is not str:
                        raise InputError('header pair')
                    pairs_out.append((
                        context.template(text(key), 'case/%d/frame/%d/h/%d/n'
                                         % (case_index, index, pair_index)),
                        context.template(text(value), 'case/%d/frame/%d/h/%d/v'
                                         % (case_index, index, pair_index))))
            else:
                listing = sequence(frame['data_to_transfered'], PAIRS_PER_BLOCK)
                for pair_index, pair in enumerate(listing):
                    if type(pair) is not list or len(pair) != 2:
                        raise InputError('header pair')
                    if type(pair[0]) is not str or type(pair[1]) is not str:
                        raise InputError('header pair')
                    pairs_out.append((
                        context.template(text(pair[0]), 'case/%d/frame/%d/h/%d/n'
                                         % (case_index, index, pair_index)),
                        context.template(text(pair[1]), 'case/%d/frame/%d/h/%d/v'
                                         % (case_index, index, pair_index))))
            compiled.append({'Type': 'headers', 'data_to_transfered': pairs_out,
                             'End_Stream': end})
        else:
            data = frame['data_to_transfered']
            if type(data) is not str:
                raise InputError('frame data')
            compiled.append({'Type': kind,
                             'data_to_transfered': context.template(
                                 text(data), 'case/%d/frame/%d/data'
                                 % (case_index, index)),
                             'End_Stream': end})
    return compiled, pause_total


def compile_document(document):
    """Validate the whole document and compile every template."""
    exact(document, ROOT_KEYS)
    seed = text(document['seed'], 64)
    if SEED.fullmatch(seed) is None:
        raise InputError('seed')
    definitions = sequence(document['definitions'], MAX_DEFINITIONS)
    context = Context(definitions, seed)
    timeout = integer(document['timeout_ms'], 1, 10 ** 9)
    cases = sequence(document['cases'], MAX_CASES)
    names = set()
    budget = 0
    header_pairs = 0
    compiled_cases = []
    for case in cases:
        exact(case, ('name', 'frames', 'expect'))
        name = text(case['name'], NAME_LIMIT)
        if NAME.fullmatch(name) is None or name in names:
            raise InputError('case name')
        names.add(name)
        expect = case['expect']
        exact(expect, ('method', 'target', 'host'))
        if TOKEN.fullmatch(expect_identity(expect['method'])) is None:
            raise InputError('expected method')
        expect_identity(expect['target'])
        expect_identity(expect['host'])
        frames = sequence(case['frames'], COMBINED_BUDGET)
        budget += len(frames)
        compiled, pause_total = compile_frames(frames, context, len(compiled_cases))
        if pause_total + timeout > MAX:
            raise InputError('time overflow')
        compiled_cases.append({'name': name, 'expect': expect, '_frames': compiled})
    payload = compile_cases(compiled_cases, context)
    records = sequence(document['events'], COMBINED_BUDGET)
    budget += len(records)
    events = []
    for index, record in enumerate(records):
        if type(record) is not dict:
            raise InputError('event')
        kind = record.get('kind')
        if type(kind) is not str:
            raise InputError('event kind')
        kind = text(kind, NAME_LIMIT)
        if kind == 'close':
            exact(record, ('at', 'kind'))
            events.append({'kind': 'close', 'at': integer(record['at'])})
            continue
        if kind not in ('headers', 'data'):
            raise InputError('event kind')
        keys = ('at', 'kind', 'stream', 'end', 'fields' if kind == 'headers' else 'data')
        exact(record, keys)
        row = {'kind': kind, 'at': integer(record['at']),
               'stream': integer(record['stream'], 0, (1 << 32) - 1)}
        if type(record['end']) is not bool:
            raise InputError('event end')
        row['end'] = record['end']
        if kind == 'headers':
            fields = sequence(record['fields'], PAIRS_PER_BLOCK)
            header_pairs += len(fields)
            compiled_fields = []
            for pair_index, pair in enumerate(fields):
                if type(pair) is not list or len(pair) != 2:
                    raise InputError('event field pair')
                if type(pair[0]) is not str or type(pair[1]) is not str:
                    raise InputError('event field pair')
                compiled_fields.append((
                    context.template(text(pair[0]), 'event/%d/h/%d/n' % (index, pair_index)),
                    context.template(text(pair[1]), 'event/%d/h/%d/v' % (index, pair_index))))
            row['fields'] = compiled_fields
        else:
            data = record['data']
            if type(data) is not str:
                raise InputError('event data')
            row['data'] = context.template(text(data), 'event/%d/data' % index)
        events.append(row)
    channels = sequence(document['channels'], MAX_CHANNELS)
    channel_names = set()
    compiled_channels = []
    for channel_index, channel in enumerate(channels):
        exact(channel, ('name', 'parts'))
        name = text(channel['name'], NAME_LIMIT)
        if NAME.fullmatch(name) is None or name in channel_names:
            raise InputError('channel name')
        channel_names.add(name)
        parts = sequence(channel['parts'], COMBINED_BUDGET)
        budget += len(parts)
        compiled_parts = []
        for part_index, part in enumerate(parts):
            exact(part, ('case', 'data'))
            owner = part['case']
            if owner is not None:
                if type(owner) is not str or text(owner, NAME_LIMIT) not in names:
                    raise InputError('owner label')
            data = part['data']
            if type(data) is not str:
                raise InputError('part data')
            compiled_parts.append({
                'case': owner,
                'data': context.template(text(data), 'channel/%d/part/%d/data'
                                         % (channel_index, part_index))})
        compiled_channels.append({'name': name, 'parts': compiled_parts})
    if budget > COMBINED_BUDGET or header_pairs > PAIR_BUDGET:
        raise InputError('combined budget')
    return compiled_cases, payload, events, compiled_channels, timeout


def run(document):
    cases, payload, events, channels, timeout = compile_document(document)
    fuzzer = FuzzExecutor()
    case_records = fuzzer.send_payload(payload, events, timeout)
    channel_records = audit_channels(channels, cases, case_records)
    return {'cases': case_records, 'channels': channel_records}


def main():
    gc.disable()
    try:
        raw = sys.stdin.buffer.read(INPUT_LIMIT + 1)
        if len(raw) > INPUT_LIMIT:
            raise InputError('input bytes')
        document = json.loads(raw.decode('utf8'), object_pairs_hook=pairs,
                              parse_constant=bad_constant, parse_float=finite_float)
        result = run(document)
    except (ValueError, TypeError, KeyError, IndexError, AttributeError,
            UnicodeError, RecursionError, ArithmeticError):
        result = {'error': 'input'}
    encoded = json.dumps(result, ensure_ascii=True, separators=(',', ':'),
                         allow_nan=False).encode('ascii')
    sys.stdout.buffer.write(encoded + b'\n')


if __name__ == '__main__':
    main()

"""Origin framing and evidence audit extension.

Parses consecutive HTTP/1.1 requests from a compressed channel capture,
materializing only bounded head windows while body fingerprints are computed
directly from the rope, and derives the paired provenance diagnostics.
"""
import re
from bisect import bisect_right

from modules.byte_program import (BASE, MOD, ByteWindow, concat_all,
                                  empty_fingerprint, fingerprint, hash_bytes,
                                  range_hash)

TOKEN = re.compile(rb"[!#$%&'*+.^_`|~0-9A-Za-z-]+\Z")
TARGET = re.compile(rb'[\x21-\x7e]+\Z')
FIELD_VALUE = re.compile(rb'[\x20-\x7e\x09]*\Z')
DECIMAL = re.compile(rb'[0-9]+\Z')
HEX = re.compile(rb'[0-9a-fA-F]+\Z')
LINE_LIMIT = 8192
LINE_WINDOW = LINE_LIMIT + 2
BLOCK_LIMIT = 65536
BLOCK_FIELDS = 128
MAX = (1 << 63) - 1
REQUEST_BUDGET = 20000
CHUNK_LINE_BUDGET = 40000
FORBIDDEN_TRAILERS = (b'host', b'content-length', b'transfer-encoding')


class ChannelError(Exception):
    """Uncommitted request terminator: 'syntax' or 'incomplete'."""

    def __init__(self, kind):
        super().__init__(kind)
        self.kind = kind


def fp_bytes(data):
    """Fingerprint object of a literal byte string."""
    return {'n': len(data), 'h': '%016x' % hash_bytes(data)}


PREFIX = [index.to_bytes(8, 'big') for index in range(8193)]


def _prefix(length):
    if length < len(PREFIX):
        return PREFIX[length]
    return length.to_bytes(8, 'big')


def field_block(fields):
    """Fingerprint object of an encoded field block."""
    out = bytearray()
    out += _prefix(len(fields))
    for name, value in fields:
        out += _prefix(len(name))
        out += name
        out += _prefix(len(value))
        out += value
    return fp_bytes(bytes(out))


class CaptureParser:
    """Sequential HTTP/1.1 request reader over one channel capture."""

    def __init__(self, seq, budget):
        self.seq = seq
        self.window = ByteWindow(seq)
        self.total = seq.n
        self.pos = 0
        self.budget = budget

    # -- line level -----------------------------------------------------
    def read_line(self):
        buffer, offset, available = self.window.view(LINE_WINDOW)
        if available <= 0:
            raise ChannelError('incomplete')
        index = buffer.find(b'\n', offset, offset + available)
        if index < 0:
            if available >= LINE_WINDOW:
                raise ChannelError('syntax')
            raise ChannelError('incomplete')
        if index == offset or buffer[index - 1] != 0x0d:
            raise ChannelError('syntax')
        length = index - 1 - offset
        if length > LINE_LIMIT:
            raise ChannelError('syntax')
        content = bytes(buffer[offset:index - 1])
        self.window.advance(index + 1 - offset)
        self.pos = self.window.pos
        return content

    def read_field(self, content):
        colon = content.find(b':')
        if colon <= 0:
            raise ChannelError('syntax')
        name = content[:colon]
        if TOKEN.fullmatch(name) is None:
            raise ChannelError('syntax')
        raw = content[colon + 1:]
        if FIELD_VALUE.fullmatch(raw) is None:
            raise ChannelError('syntax')
        return name, raw.strip(b' \t')

    # -- request level --------------------------------------------------
    def parse(self):
        requests = []
        error = None
        while self.pos < self.total:
            start = self.pos
            try:
                requests.append(self.parse_request(start))
            except ChannelError as exc:
                error = {'kind': exc.kind, 'offset': start}
                break
            self.budget['requests'] += 1
            if self.budget['requests'] > REQUEST_BUDGET:
                raise ValueError('origin request budget')
        return requests, error

    def parse_request(self, start):
        content = self.read_line()
        parts = content.split(b' ')
        if len(parts) != 3:
            raise ChannelError('syntax')
        method, target, version = parts
        if TOKEN.fullmatch(method) is None:
            raise ChannelError('syntax')
        if TARGET.fullmatch(target) is None:
            raise ChannelError('syntax')
        if version != b'HTTP/1.1':
            raise ChannelError('syntax')
        block = len(content) + 2
        if block > BLOCK_LIMIT:
            raise ChannelError('syntax')
        fields = []
        while True:
            content = self.read_line()
            block += len(content) + 2
            if block > BLOCK_LIMIT:
                raise ChannelError('syntax')
            if not content:
                break
            if len(fields) >= BLOCK_FIELDS:
                raise ChannelError('syntax')
            fields.append(self.read_field(content))
        framing, length, host_count, host_value, cl_values, te_count = self.framing(fields)
        body_n, body_h, trailers = self.parse_body(framing, length)
        return (start, self.pos, method, target, host_count, host_value, fields,
                body_n, body_h, trailers, framing)

    @staticmethod
    def framing(fields):
        host_count = 0
        host_value = None
        cl_values = []
        te_count = 0
        te_value = None
        for name, value in fields:
            low = name.lower()
            if low == b'host':
                host_count += 1
                host_value = value
            elif low == b'content-length':
                for member in value.split(b','):
                    member = member.strip(b' \t')
                    if not member or DECIMAL.fullmatch(member) is None:
                        raise ChannelError('syntax')
                    number = int(member)
                    if number > MAX:
                        raise ChannelError('syntax')
                    cl_values.append(number)
            elif low == b'transfer-encoding':
                te_count += 1
                te_value = value
        if te_count:
            if te_count > 1 or cl_values or te_value.lower() != b'chunked':
                raise ChannelError('syntax')
            return 'chunked', 0, host_count, host_value, cl_values, te_count
        if cl_values:
            if any(value != cl_values[0] for value in cl_values):
                raise ChannelError('syntax')
            return 'length', cl_values[0], host_count, host_value, cl_values, te_count
        return 'none', 0, host_count, host_value, cl_values, te_count

    def parse_body(self, framing, length):
        if framing == 'none':
            return 0, 0, []
        if framing == 'length':
            if self.pos + length > self.total:
                raise ChannelError('incomplete')
            span = range_hash(self.seq, self.pos, self.pos + length)
            self.window.advance(length)
            self.pos = self.window.pos
            return span[0], span[1], []
        return self.parse_chunked()

    def parse_chunked(self):
        body_n = 0
        body_h = 0
        while True:
            content = self.read_line()
            self.budget['lines'] += 1
            if self.budget['lines'] > CHUNK_LINE_BUDGET:
                raise ValueError('chunk-size line budget')
            semi = content.find(b';')
            if semi >= 0:
                size_part = content[:semi]
                if FIELD_VALUE.fullmatch(content[semi + 1:]) is None:
                    raise ChannelError('syntax')
            else:
                size_part = content
            if not size_part or HEX.fullmatch(size_part) is None:
                raise ChannelError('syntax')
            value = int(size_part, 16)
            if value > MAX:
                raise ChannelError('syntax')
            if not value:
                return body_n, body_h, self.parse_trailers()
            if self.pos + value > self.total:
                raise ChannelError('incomplete')
            span = range_hash(self.seq, self.pos, self.pos + value)
            body_h = (body_h * pow(BASE, span[0], MOD) + span[1]) % MOD
            body_n += span[0]
            self.window.advance(value)
            self.pos = self.window.pos
            buffer, offset, available = self.window.view(2)
            if available < 2:
                raise ChannelError('incomplete')
            if buffer[offset] != 0x0d or buffer[offset + 1] != 0x0a:
                raise ChannelError('syntax')
            self.window.advance(2)
            self.pos = self.window.pos

    def parse_trailers(self):
        fields = []
        block = 0
        while True:
            content = self.read_line()
            block += len(content) + 2
            if block > BLOCK_LIMIT:
                raise ChannelError('syntax')
            if not content:
                break
            if len(fields) >= BLOCK_FIELDS:
                raise ChannelError('syntax')
            name, value = self.read_field(content)
            if name.lower() in FORBIDDEN_TRAILERS:
                raise ChannelError('syntax')
            fields.append((name, value))
        return fields


def span_owners(bounds, labels, start, end):
    """Attribution of the raw request span as merged [label, count] pairs."""
    index = bisect_right(bounds, start) - 1
    while index < len(labels) and bounds[index + 1] <= start:
        index += 1
    counts = {}
    order = []
    while index < len(labels) and bounds[index] < end:
        low = bounds[index] if bounds[index] > start else start
        high = bounds[index + 1] if bounds[index + 1] < end else end
        if high > low:
            label = labels[index]
            if label not in counts:
                counts[label] = 0
                order.append(label)
            counts[label] += high - low
        index += 1
    return [(label, counts[label]) for label in order]


def audit_channel(channel, expect, positions, case_records, owner_seen,
                  origin_counts, case_flags, budget):
    """Parse one channel and emit its record with provenance flags."""
    parts = channel['parts']
    labels = [part['case'] for part in parts]
    seqs = [part['data'] for part in parts]
    seq = concat_all(seqs)
    bounds = [0]
    for item in seqs:
        bounds.append(bounds[-1] + item.n)
    parser = CaptureParser(seq, budget)
    requests, error = parser.parse()
    ends = [record[1] for record in requests]
    committed = [bisect_right(ends, bound) for bound in bounds[1:]]
    records = []
    for item in requests:
        (start, end, method, target, host_count, host_value, fields,
         body_n, body_h, trailers, framing) = item
        owners = span_owners(bounds, labels, start, end)
        owner = owners[0][0] if owners else None
        flags = set()
        if owner is None:
            flags.add('unattributed')
        if any(label != owner for label, _ in owners):
            flags.add('mixed_owner')
        if host_count == 0:
            flags.add('missing_host')
        elif host_count > 1:
            flags.add('multiple_host')
        if owner is not None:
            wanted = expect[owner]
            record = case_records[positions[owner]]
            if (method != wanted['method'].encode('ascii')
                    or target != wanted['target'].encode('ascii')):
                flags.add('identity')
            elif host_count != 1 or host_value.lower() != wanted['host'].encode('ascii').lower():
                flags.add('identity')
            seen = owner_seen.get(owner, 0) + 1
            owner_seen[owner] = seen
            if seen > 1:
                flags.add('extra')
            if record['request_frames'] == 0:
                flags.add('unsent')
            index = positions[owner]
            origin_counts[index] += 1
            if 'identity' in flags:
                case_flags[index].add('identity')
            if 'mixed_owner' in flags:
                case_flags[index].add('mixed_origin')
        records.append({
            'start': start,
            'end': end,
            'method': fp_bytes(method),
            'target': fp_bytes(target),
            'host': fp_bytes(host_value.lower()) if host_count == 1 else empty_fingerprint(),
            'host_count': host_count,
            'headers': field_block(fields),
            'body': {'n': body_n, 'h': '%016x' % body_h},
            'trailers': field_block(trailers),
            'framing': framing,
            'owner': owner,
            'owners': owners,
            'flags': sorted(flags),
        })
    return {'name': channel['name'], 'bytes': fingerprint(seq),
            'requests': records, 'committed': committed, 'error': error}


def audit_channels(channels, cases, case_records):
    """Audit all captures and finish the paired case diagnostics."""
    expect = {}
    positions = {}
    for index, case in enumerate(cases):
        expect[case['name']] = case['expect']
        positions[case['name']] = index
    owner_seen = {}
    origin_counts = [0] * len(cases)
    case_flags = [set() for _ in range(len(cases))]
    budget = {'requests': 0, 'lines': 0}
    records = []
    for channel in channels:
        records.append(audit_channel(channel, expect, positions, case_records,
                                     owner_seen, origin_counts, case_flags, budget))
    for index, record in enumerate(case_records):
        flags = case_flags[index]
        count = origin_counts[index]
        frames = record['request_frames']
        if frames > 0 and count == 0:
            flags.add('missing_origin')
        if count > 1:
            flags.add('extra_origin')
        if count > 0 and frames == 0:
            flags.add('unsent_origin')
        record['origin_count'] = count
        record['flags'] = sorted(flags)
    return records

"""FuzzExecutor frame conversion and execution against an injected transport."""
from typing import Any, Dict, List

from HTTP3_Just_Send import HttpClient
from modules.byte_program import EMPTY, concat, fingerprint, leaf, size
from modules.clock import Clock
from modules.events import (ConnectionTerminated, DataReceived, HeadersReceived,
                            SendError)


def encoded_action(at, stream, kind, data, end=False):
    """Exact receipt encoding of one emitted or accepted action."""
    head = leaf(at.to_bytes(8, 'big') + stream.to_bytes(4, 'big') + kind.encode('ascii'))
    if kind in ('H', 'h'):
        pairs = list(data)
        content = leaf(len(pairs).to_bytes(8, 'big'))
        for name, value in pairs:
            content = concat(content, leaf(size(name).to_bytes(8, 'big')))
            content = concat(content, name)
            content = concat(content, leaf(size(value).to_bytes(8, 'big')))
            content = concat(content, value)
    else:
        content = concat(leaf(size(data).to_bytes(8, 'big')), data)
    return concat(concat(head, content), leaf(bytes((1 if end else 0,))))


class CaseAccount:
    """Per case emission and reception bookkeeping."""

    __slots__ = ('sent', 'received', 'body', 'frames', 'request_frames',
                 'payload_bytes', 'response_frames')

    def __init__(self):
        self.sent = EMPTY
        self.received = EMPTY
        self.body = EMPTY
        self.frames = 0
        self.request_frames = 0
        self.payload_bytes = 0
        self.response_frames = 0


class OfflineTransport:
    """Injected decoded-event backend recording exact client receipts."""

    def __init__(self, clock, count):
        self.clock = clock
        self.next_stream = 0
        self.ended = set()
        self.accounts = [CaseAccount() for _ in range(count)]
        self.client = None

    def get_next_available_stream_id(self):
        stream = self.next_stream
        self.next_stream += 4
        return stream

    def request_ended(self, stream_id):
        return stream_id in self.ended

    def record(self, stream_id, kind, data, end_stream=False):
        if stream_id in self.ended:
            raise SendError('frame after request end')
        index = stream_id // 4
        account = self.accounts[index]
        account.sent = concat(account.sent,
                              encoded_action(self.clock.now, stream_id, kind,
                                             data, end_stream))
        account.frames += 1
        if kind in ('H', 'D'):
            account.request_frames += 1
        if kind == 'H':
            account.payload_bytes += sum(size(name) + size(value)
                                         for name, value in data)
        else:
            account.payload_bytes += size(data)
        if end_stream:
            self.ended.add(stream_id)

    def send_headers(self, stream_id, headers, end_stream):
        self.record(stream_id, 'H', headers, end_stream)

    def send_data(self, stream_id, data, end_stream):
        self.record(stream_id, 'D', data, end_stream)

    def send_datagram(self, stream_id, data):
        self.record(stream_id, 'G', data, False)

    def dispatch(self, record):
        kind = record['kind']
        if kind == 'close':
            self.client.quic_event_received(ConnectionTerminated())
        elif kind == 'headers':
            self.client.quic_event_received(
                HeadersReceived(record['stream'], record['fields'], record['end']))
        else:
            self.client.quic_event_received(
                DataReceived(record['stream'], record['data'], record['end']))


class FuzzExecutor:
    """Drives compiled payloads through the offline client and transport."""

    def __init__(self, target_ip=None, target_port=None, domain=None):
        self.target_ip = target_ip
        self.target_port = target_port
        self.domain = domain

    def _convert_single_case_frames(self, frames: List[Any]) -> List[Dict[str, Any]]:
        converted_frames = []
        for item in frames:
            kind = item.Type
            if kind == 'headers':
                converted_frames.append({
                    'Type': 'headers',
                    'data_to_transfered': [list(pair) for pair in item.data_to_transfered],
                    'End_Stream': bool(item.End_Stream),
                })
            elif kind in ('data', 'datagram'):
                converted_frames.append({
                    'Type': kind,
                    'data_to_transfered': item.data_to_transfered,
                    'End_Stream': bool(item.End_Stream),
                })
            else:
                converted_frames.append({
                    'Type': 'sleep',
                    'Time_to_Stop': item.Time_to_Stop,
                })
        return converted_frames

